//@ run-pass
// Module-level `let` constants with EXPRESSION initializers must carry the folded value.
// Found 2026-09-01 through the e-graph Q-certificate self-tests: the lean_single seed read
// `0 - 1` as 0 (dropping everything after the first literal), which made EG_INVALID == 0 in
// every source-built Madaros and silently discarded the first node of every small e-graph;
// Madaros' own folder lacked shifts (`1 << 3` -> BSS zero). Every case below is checked
// against an in-function computation of the same expression.
let C_NEG: i64 = 0 - 1
let C_NEGLIT: i64 = -1
let C_SUM: i64 = 1 + 1
let C_MULP: i64 = (2 + 3) * 4
let C_PREC: i64 = 2 + 3 * 4
let C_SHL: i64 = 1 << 3
let C_SHR: i64 = 256 >> 4
let C_REM: i64 = 7 % 4
let C_AND: i64 = 6 & 3
let C_OR: i64 = 6 | 1
let C_XOR: i64 = 6 ^ 3
let C_BIG: i64 = 0 - 800001
let C_CHAIN: i64 = 0 - 1 - 1

fn main() -> i32 with IO {
    var bad: i64 = 0
    if C_NEG != 0 - 1 { println("FAIL C_NEG"); bad = bad + 1 }
    if C_NEGLIT != 0 - 1 { println("FAIL C_NEGLIT"); bad = bad + 1 }
    if C_SUM != 2 { println("FAIL C_SUM"); bad = bad + 1 }
    if C_MULP != 20 { println("FAIL C_MULP"); bad = bad + 1 }
    if C_PREC != 14 { println("FAIL C_PREC"); bad = bad + 1 }
    if C_SHL != 8 { println("FAIL C_SHL"); bad = bad + 1 }
    if C_SHR != 16 { println("FAIL C_SHR"); bad = bad + 1 }
    if C_REM != 3 { println("FAIL C_REM"); bad = bad + 1 }
    if C_AND != 2 { println("FAIL C_AND"); bad = bad + 1 }
    if C_OR != 7 { println("FAIL C_OR"); bad = bad + 1 }
    if C_XOR != 5 { println("FAIL C_XOR"); bad = bad + 1 }
    if C_BIG != 0 - 800001 { println("FAIL C_BIG"); bad = bad + 1 }
    if C_CHAIN != 0 - 2 { println("FAIL C_CHAIN"); bad = bad + 1 }
    // The e-graph consequence, in miniature: an id of 0 must NOT compare equal to the sentinel.
    let id: i64 = 0
    if id == C_NEG { println("FAIL sentinel: 0 == C_NEG"); bad = bad + 1 }
    if bad == 0 { println("module_let_const_expr: OK") }
    bad as i32
}

//@ run-pass
// Sprint 224: Multi-struct function calls + struct return + mutation
// Validates patterns needed by rapamycin PBPK: multi-struct args, field mutation, loops

struct State {
    x: f64,
    v: f64,
}

struct Params {
    k: f64,
    damping: f64,
    dt: f64,
}

// Euler step for damped spring: dx/dt = v, dv/dt = -k*x - damping*v
fn neg(x: f64) -> f64 {
    return 0.0 - x
}

fn euler_step(s: State, p: Params) -> State {
    let ax = neg(p.k) * s.x - p.damping * s.v
    let new_x = s.x + s.v * p.dt
    let new_v = s.v + ax * p.dt
    return State { x: new_x, v: new_v }
}

fn f64_to_int_x1000(v: f64) -> i64 {
    return (v * 1000.0) as i64
}

fn abs_f64(x: f64) -> f64 {
    if x < 0.0 { return 0.0 - x }
    return x
}

fn main() -> i64 with IO, Mut {
    let prm = Params { k: 1.0, damping: 0.1, dt: 0.01 }

    // T1: basic struct creation + function call
    var s = State { x: 1.0, v: 0.0 }
    s = euler_step(s, prm)
    let t1_x = f64_to_int_x1000(s.x)
    print("T1_x=")
    print_int(t1_x)
    print("\n")

    // T2: 100-step simulation loop
    var s2 = State { x: 1.0, v: 0.0 }
    var i = 0
    while i < 100 {
        s2 = euler_step(s2, prm)
        i = i + 1
    }
    let t2_x = f64_to_int_x1000(s2.x)
    print("T2_x=")
    print_int(t2_x)
    print("\n")

    // T3: 1000-step simulation — should oscillate and damp
    var s3 = State { x: 1.0, v: 0.0 }
    var j = 0
    while j < 1000 {
        s3 = euler_step(s3, prm)
        j = j + 1
    }
    let t3_x = f64_to_int_x1000(s3.x)
    print("T3_x=")
    print_int(t3_x)
    print("\n")

