        if x0 != 1 { return 0 }
    }
    if x1 != 0 {
        if x1 != 1 { return 0 }
    }
    if x2 != 0 {
        if x2 != 1 { return 0 }
    }
    return 1
}

fn assignment_code(x: i64) -> i64 {
